use fixture::parse_args;

fn error_for(args: &[&str], culprit: &str) {
    match parse_args(args) {
        Ok(options) => panic!("{args:?} should fail, got {options:?}"),
        Err(message) => assert!(
            message.contains(culprit),
            "error for {args:?} should mention {culprit:?}: {message:?}"
        ),
    }
}

#[test]
fn defaults() {
    let options = parse_args(&[]).unwrap();
    assert!(!options.verbose);
    assert_eq!(options.output, None);
    assert_eq!(options.jobs, 1);
    assert!(options.inputs.is_empty());
}

#[test]
fn output_forms() {
    assert_eq!(parse_args(&["-o", "out.bin"]).unwrap().output.as_deref(), Some("out.bin"));
    assert_eq!(parse_args(&["--output", "a"]).unwrap().output.as_deref(), Some("a"));
    assert_eq!(parse_args(&["--output=b=c"]).unwrap().output.as_deref(), Some("b=c"));
    assert_eq!(parse_args(&["-o", "-"]).unwrap().output.as_deref(), Some("-"));
    assert_eq!(parse_args(&["-o", "--verbose"]).unwrap().output.as_deref(), Some("--verbose"));
    let last = parse_args(&["-o", "first", "--output=second"]).unwrap();
    assert_eq!(last.output.as_deref(), Some("second"));
    assert!(!last.verbose);
    assert!(last.inputs.is_empty());
}

#[test]
fn jobs_forms() {
    assert_eq!(parse_args(&["-j", "4"]).unwrap().jobs, 4);
    assert_eq!(parse_args(&["--jobs", "16"]).unwrap().jobs, 16);
    assert_eq!(parse_args(&["--jobs=2", "-j", "3"]).unwrap().jobs, 3);
    error_for(&["-j", "0"], "0");
    error_for(&["--jobs=-1"], "-1");
    error_for(&["-j", "four"], "four");
    assert!(parse_args(&["--jobs", ""]).is_err());
    error_for(&["--jobs="], "--jobs");
}

#[test]
fn missing_values() {
    error_for(&["-o"], "-o");
    error_for(&["a", "--output"], "--output");
    error_for(&["--output="], "--output");
    error_for(&["-j"], "-j");
}

#[test]
fn inputs_and_terminator() {
    let options = parse_args(&["a", "-", "-v", "b", "--", "-o", "--jobs=9", "--"]).unwrap();
    assert!(options.verbose);
    assert_eq!(options.inputs, ["a", "-", "b", "-o", "--jobs=9", "--"]);
    assert_eq!(options.output, None);
    assert_eq!(options.jobs, 1);
}

#[test]
fn unknown_options() {
    error_for(&["--bogus"], "--bogus");
    error_for(&["a", "-x", "b"], "-x");
    error_for(&["-vo", "file"], "-vo");
    error_for(&["--verbose=yes"], "--verbose=yes");
    error_for(&["--out", "x"], "--out");
}

#[test]
fn combined() {
    let options = parse_args(&["--verbose", "in1", "-j", "8", "--output", "dist", "in2"]).unwrap();
    assert!(options.verbose);
    assert_eq!(options.jobs, 8);
    assert_eq!(options.output.as_deref(), Some("dist"));
    assert_eq!(options.inputs, ["in1", "in2"]);
}
